    3. The months should not be less than 1 or higher than 12.
    4. The date should be in the format: mm-dd-yyyy
    """
    if not date:
        return False

    parts = date.split('-')
    if len(parts) != 3:
        return False

    try:
        # Check if parts have correct lengths (mm-dd-yyyy)
        if len(parts[0]) != 2 or len(parts[1]) != 2 or len(parts[2]) != 4:
            return False

        month = int(parts[0])
        day = int(parts[1])
        year = int(parts[2])
    except ValueError:
        return False

    if month < 1 or month > 12:
        return False

    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    elif month == 2:
        if day < 1 or day > 29:
            return False

    return True
