    min_val = float('inf')
    min_pos = (0, 0)
    for r in range(N):
        for c in range(N):
            if grid[r][c] < min_val:
                min_val = grid[r][c]
                min_pos = (r, c)

    # The lexicographically smallest path must start with the minimum value.
    # To make it as small as possible, we want the second element to be the 
    # minimum possible neighbor of the minimum value.
    # Once we find the smallest neighbor 'min_neighbor', the best strategy
    # to minimize the sequence is to oscillate between 'min_val' and 'min_neighbor'
    # because 'min_val' is the smallest overall value in the grid.

    r, c = min_pos
    min_neighbor = float('inf')
    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < N and 0 <= nc < N:
            min_neighbor = min(min_neighbor, grid[nr][nc])

    res = []
    for i in range(k):
        if i % 2 == 0:
            res.append(min_val)
        else:
            res.append(min_neighbor)

