            if grid[r][c] == min_val:
                starts.append((r, c))

    # For each starting cell, find the minimum neighbor
    overall_min_neighbor = float('inf')
    for r, c in starts:
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                overall_min_neighbor = min(overall_min_neighbor, grid[nr][nc])

    res = []
    for i in range(k):
        if i % 2 == 0:
            res.append(min_val)
        else:
            res.append(overall_min_neighbor)

    return res
